/* SPDX-License-Identifier: Apache-2.0
 *
 * Example Zephyr application that configures an ADC channel with hardware
 * oversampling and continuously reads averaged samples.
 *
 * Target board: nrf52840dk/nrf52840
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

#define ADC_RESOLUTION        12      /* 12‑bit resolution */
#define ADC_OVERSAMPLING      4       /* 2^4 = 16 hardware samples averaged */
#define ADC_CHANNEL_ID        0       /* Channel 0 (AIN0 on nRF52840) */

static const struct device *adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));

/* Single sample buffer – the hardware averaging will already produce an
 * averaged value, so one element is enough.
 */
static int16_t sample_buffer[1];

void main(void)
{
    int ret;

    if (!device_is_ready(adc_dev)) {
        printk("ADC device not ready\n");
        return;
    }

    /* Configure the ADC channel */
    struct adc_channel_cfg channel_cfg = {
        .gain             = ADC_GAIN_1,
        .reference        = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id       = ADC_CHANNEL_ID,
        /* For nRF SAADC the positive input for channel 0 is AIN0.
         * Using the generic macro works across supported drivers.
         */
        .input_positive   = 0,
        .input_negative   = ADC_INPUT_NEGATIVE_UNUSED,
    };

    ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret) {
        printk("Failed to setup ADC channel (err %d)\n", ret);
        return;
    }

    /* Define the ADC read sequence */
    struct adc_sequence sequence = {
        .channels      = BIT(ADC_CHANNEL_ID),
        .buffer        = sample_buffer,
        .buffer_size   = sizeof(sample_buffer),
        .resolution    = ADC_RESOLUTION,
        .oversampling  = ADC_OVERSAMPLING,
        .calibrate     = false,
    };

    printk("Starting ADC read loop (resolution %d‑bit, oversampling 2^%d)\n",
           ADC_RESOLUTION, ADC_OVERSAMPLING);

    while (1) {
        ret = adc_read(adc_dev, &sequence);
        if (ret) {
            printk("ADC read error: %d\n", ret);
        } else {
            printk("Raw ADC value: %d\n", sample_buffer[0]);
        }

        k_sleep(K_SECONDS(1));
    }
}
